/**
 * Plain Huffman Tree Visualizer
 * Renders the complete, static Huffman tree generated by the C backend
 */
const TreeVisualizer = {
  treeData: null,
  
  // Viewport transforms (Pan & Zoom)
  scale: 1,
  panX: 0,
  panY: 0,
  isPanning: false,
  startX: 0,
  startY: 0,

  canvas: null,
  ctx: null,
  nodeMap: new Map(),

  init() {
    this.canvas = document.getElementById('tree-canvas');
    if (!this.canvas) return;
    this.ctx = this.canvas.getContext('2d');

    this.resizeCanvas();
    window.addEventListener('resize', () => {
      this.resizeCanvas();
      this.draw();
    });

    this.setupEvents();
  },

  resizeCanvas() {
    if (!this.canvas) return;
    const rect = this.canvas.parentElement.getBoundingClientRect();
    this.canvas.width = rect.width;
    this.canvas.height = rect.height || 540;
  },

  setupEvents() {
    const stage = document.getElementById('tree-stage');
    if (!stage) return;

    stage.addEventListener('mousedown', (e) => {
      this.isPanning = true;
      this.startX = e.clientX - this.panX;
      this.startY = e.clientY - this.panY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!this.isPanning) return;
      this.panX = e.clientX - this.startX;
      this.panY = e.clientY - this.startY;
      this.draw();
    });

    window.addEventListener('mouseup', () => {
      this.isPanning = false;
    });

    stage.addEventListener('wheel', (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.15 : 0.85;
      this.zoom(zoomFactor, e.clientX, e.clientY);
    });

    document.getElementById('viz-zoom-in')?.addEventListener('click', () => this.zoom(1.2));
    document.getElementById('viz-zoom-out')?.addEventListener('click', () => this.zoom(0.8));
    document.getElementById('viz-fit')?.addEventListener('click', () => this.fitView());
  },

  loadTree(data) {
    this.treeData = data;
    this.nodeMap.clear();

    if (data.nodes) {
      for (const n of data.nodes) {
        this.nodeMap.set(n.id, n);
      }
    }

    this.renderCodebook(data.codes);
    this.fitView();
  },

  zoom(factor) {
    const newScale = Math.max(0.2, Math.min(3.5, this.scale * factor));
    const cx = this.canvas.width / 2;
    const cy = this.canvas.height / 2;

    this.panX = cx - (cx - this.panX) * (newScale / this.scale);
    this.panY = cy - (cy - this.panY) * (newScale / this.scale);
    this.scale = newScale;
    this.draw();
  },

  fitView() {
    this.resizeCanvas();
    const canvasW = this.canvas.width || 900;
    
    if (!this.treeData || !this.treeData.root_id) {
      this.scale = 1;
      this.panX = canvasW / 2;
      this.panY = 60;
      this.draw();
      return;
    }

    const rootNode = this.nodeMap.get(this.treeData.root_id);
    if (!rootNode) return;
    
    const layout = this.computeSubtreeLayout(rootNode, 0);
    const treeW = Math.max(80, layout.maxX - layout.minX);
    
    let targetScale = 1;
    if (treeW + 120 > canvasW) {
      targetScale = Math.max(0.3, Math.min(1.0, (canvasW - 120) / treeW));
    }
    this.scale = targetScale;
    
    const treeCenterX = (layout.minX + layout.maxX) / 2;
    this.panX = canvasW / 2 - treeCenterX * this.scale;
    this.panY = 60;
    this.draw();
  },

  draw() {
    if (!this.ctx || !this.canvas) return;
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

    if (!this.treeData || this.treeData.empty) {
      ctx.fillStyle = '#65717D';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('No tree data available. Upload or select a file first.', this.canvas.width / 2, this.canvas.height / 2);
      return;
    }

    ctx.save();
    ctx.translate(this.panX, this.panY);
    ctx.scale(this.scale, this.scale);

    // Render plain completed Huffman tree
    const rootNode = this.nodeMap.get(this.treeData.root_id);
    if (rootNode) {
      const layout = this.computeSubtreeLayout(rootNode, 0);
      this.renderSubtree(ctx, layout);
    }

    ctx.restore();
  },

  computeSubtreeLayout(node, depth) {
    const layoutNode = {
      node: node,
      x: 0,
      y: depth * 85,
      minX: 0,
      maxX: 0,
      width: 0,
      left: null,
      right: null
    };

    if (node.is_leaf || (!node.left_id && !node.right_id)) {
      layoutNode.minX = -32;
      layoutNode.maxX = 32;
      layoutNode.width = 64;
      return layoutNode;
    }

    const leftChild = node.left_id !== null ? this.nodeMap.get(node.left_id) : null;
    const rightChild = node.right_id !== null ? this.nodeMap.get(node.right_id) : null;

    let leftLayout = leftChild ? this.computeSubtreeLayout(leftChild, depth + 1) : null;
    let rightLayout = rightChild ? this.computeSubtreeLayout(rightChild, depth + 1) : null;

    layoutNode.left = leftLayout;
    layoutNode.right = rightLayout;

    if (leftLayout && rightLayout) {
      const spacing = 36;
      const leftShift = -((leftLayout.maxX - leftLayout.minX) / 2 + spacing);
      const rightShift = ((rightLayout.maxX - rightLayout.minX) / 2 + spacing);

      this.shiftLayoutX(leftLayout, leftShift);
      this.shiftLayoutX(rightLayout, rightShift);

      layoutNode.minX = leftLayout.minX + leftShift;
      layoutNode.maxX = rightLayout.maxX + rightShift;
      layoutNode.width = layoutNode.maxX - layoutNode.minX;
      layoutNode.x = 0;
    } else if (leftLayout) {
      layoutNode.minX = leftLayout.minX;
      layoutNode.maxX = leftLayout.maxX;
      layoutNode.width = leftLayout.width;
      layoutNode.x = 0;
    } else {
      layoutNode.minX = -32;
      layoutNode.maxX = 32;
      layoutNode.width = 64;
      layoutNode.x = 0;
    }

    return layoutNode;
  },

  shiftLayoutX(layout, deltaX) {
    if (!layout) return;
    layout.x += deltaX;
    layout.minX += deltaX;
    layout.maxX += deltaX;
    if (layout.left) this.shiftLayoutX(layout.left, deltaX);
    if (layout.right) this.shiftLayoutX(layout.right, deltaX);
  },

  renderSubtree(ctx, layout) {
    if (!layout) return;

    // Draw edges
    if (layout.left) {
      this.drawEdge(ctx, layout.x, layout.y, layout.left.x, layout.left.y, '0');
      this.renderSubtree(ctx, layout.left);
    }
    if (layout.right) {
      this.drawEdge(ctx, layout.x, layout.y, layout.right.x, layout.right.y, '1');
      this.renderSubtree(ctx, layout.right);
    }

    // Draw node
    this.drawNode(ctx, layout);
  },

  drawEdge(ctx, x1, y1, x2, y2, bit) {
    ctx.beginPath();
    ctx.moveTo(x1, y1 + 18);
    ctx.lineTo(x2, y2 - 18);
    ctx.strokeStyle = '#DCD5C8';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Edge bit label
    const midX = (x1 + x2) / 2;
    const midY = (y1 + y2) / 2;

    ctx.fillStyle = '#FFFFFF';
    ctx.beginPath();
    ctx.arc(midX, midY, 9, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#DCD5C8';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.fillStyle = bit === '0' ? '#D97757' : '#202A35';
    ctx.font = 'bold 10px monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(bit, midX, midY);
  },

  drawNode(ctx, layout) {
    const node = layout.node;
    const x = layout.x;
    const y = layout.y;
    const isLeaf = node.is_leaf;

    const bgColor = isLeaf ? '#F5F1E8' : '#FFFFFF';
    const borderColor = isLeaf ? '#D97757' : '#202A35';
    const borderWidth = 2;
    const radius = isLeaf ? 22 : 18;

    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fillStyle = bgColor;
    ctx.fill();
    ctx.strokeStyle = borderColor;
    ctx.lineWidth = borderWidth;
    ctx.stroke();

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    if (isLeaf) {
      const symLabel = node.label.startsWith("'") ? node.label.substring(1, 2) : (node.label.length > 4 ? node.label.substring(0, 3) : node.label);
      ctx.fillStyle = '#202A35';
      ctx.font = 'bold 12px sans-serif';
      ctx.fillText(symLabel, x, y - 5);

      ctx.fillStyle = '#65717D';
      ctx.font = '10px monospace';
      ctx.fillText(`${node.freq}`, x, y + 8);
    } else {
      ctx.fillStyle = '#202A35';
      ctx.font = 'bold 11px monospace';
      ctx.fillText(`${node.freq}`, x, y);
    }
  },

  renderCodebook(codes) {
    const tbody = document.getElementById('codebook-body');
    if (!tbody) return;
    tbody.innerHTML = '';

    if (!codes || Object.keys(codes).length === 0) {
      tbody.innerHTML = `<tr><td colspan="5" style="text-align:center; padding:1.5rem;">No codes generated yet.</td></tr>`;
      return;
    }

    const list = Object.entries(codes).map(([sym, info]) => ({
      sym: parseInt(sym, 10),
      ...info
    }));

    list.sort((a, b) => a.length - b.length || a.sym - b.sym);

    list.forEach(item => {
      const tr = document.createElement('tr');
      const hex = '0x' + item.sym.toString(16).toUpperCase().padStart(2, '0');
      const totalBits = (item.freq * item.length).toLocaleString();

      tr.innerHTML = `
        <td><strong class="code-pill">${item.label}</strong></td>
        <td class="mono">${hex}</td>
        <td class="mono">${item.freq.toLocaleString()}</td>
        <td><span class="mono" style="font-weight:700; color:var(--terracotta);">${item.code}</span></td>
        <td class="mono">${item.length} bits (${totalBits} total)</td>
      `;
      tbody.appendChild(tr);
    });
  }
};
